(function(){
 'use strict';
 const P=window.ExamPolicy;
 const link=key=>`<a href="${P.sources[key].url}" target="_blank" rel="noopener noreferrer">${P.sources[key].title} ↗</a>`;
 const fmt=s=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s));
 const btn=document.createElement('button');btn.className='nav';btn.dataset.tab='policy';btn.textContent='报考与备考';document.querySelector('.topbar nav').append(btn);
 const view=document.createElement('section');view.id='policyView';view.hidden=true;document.querySelector('#main').append(view);
 view.innerHTML=`<div class="eyebrow">2027 · OFFICIAL GUIDE</div><h1>把重要的事，提前记住。</h1><p class="muted">依据2027年度公告与指南 · 核验于${P.verifiedAt} · 时间统一为北京时间</p><div class="policy-callout"><b>实名认证：10月23日18:00截止；提交报名：10月24日18:00截止。</b><p>两项截止时间相差一天。通过资格审查后不能改报；截止前未审查或未通过的可改报，通过前请谨慎提交。</p></div><div class="policy-heading"><h2>报名时间轴</h2><button id="exportExamCalendar" class="button primary">导出日历提醒 .ics ↓</button></div><p class="small muted">日历含关键截止与笔试时间，默认设置提前24小时提醒；是否通知取决于导入后的日历设置。网页本身不会在关闭后推送。</p><div id="examTimeline" class="exam-timeline"></div><p class="small muted">报名序号自10月28日8:00起查询；成绩预计2027年1月公布，具体日期另行通知。</p><div class="policy-columns"><article class="data-card"><h2>资格判断，有这几条通则</h2><dl class="policy-faq"><dt>函授、成人教育能不能报？</dt><dd>取得毕业证后，符合岗位要求即可报考。不能仅因非全日制就判定不符合；岗位明确限制学习形式时另核对。依据：指南第1问。</dd><dt>硕士能否用本科身份报“仅限本科”？</dt><dd>非应届人员以已获得的最高学历报考；2027应届生以即将获得的最高学历报考。硕博不能报仅限本科的岗位。依据：第7问。</dd><dt>企业经验算基层工作吗？</dt><dd>各类企业工作经历在基层经历范围内，截止2026年10月；工作后的全日制学习时间不计入。岗位指定行业或岗位经历不能用总年限替代。依据：公告与指南第8、9问。</dd><dt>证书与学位什么时候取得？</dt><dd>一般资质截止2026年10月；2027应届毕业生学历学位一般截止2027年7月。依据：第15问。</dd><dt>年龄怎么核对？</dt><dd>一般出生区间为1987年10月—2008年10月；2027应届硕博放宽至1982年10月以后。公安等人民警察按层级及岗位另有规定，不能套用统一上限。依据：公告、指南第13问。</dd><dt>还要做哪些资格检查？</dt><dd>现役军人、在读非应届学生、在职公务员及参公人员不能报考；回避、处分等情形还须核对。工作台不把基础条件匹配当作最终资格审查。</dd></dl>${link('guide')}</article><article class="data-card"><h2>先看岗位，再选备考方案</h2><p>在岗位详情中查看公共科目试卷、专业科目、笔试权重及成绩试算。</p><p><b>例：广东证监局“财金类综合岗位”接受哲学专业，考试仍为财金类专业笔试。</b>法考A证不会把该岗位的专业考试变成法律类。</p><p>行测包含政治理论、常识判断、言语理解与表达、数量关系、判断推理、资料分析。申论按原表的三类考试类别区分。</p><p class="small muted">所附笔记里“新增模块/新增试卷”“两科分值权重相同”等概括，不作为所有岗位的通用规则。以当年原文与岗位考试方案为准。</p>${link('announcement')}<h3>材料与来源</h3><p class="small">已区分笔记摘要与所附原文。证监会四份大纲用于生成范围摘要；已从证监会官网下载附件，并以SHA-256确认四份文件与所附DOC逐字节一致（2026年10月18日）。职位XLS仍为用户提供版本，未逐岗与官网对照。</p>${link('csrc')}</article></div>`;
 function timeline(){document.querySelector('#examTimeline').innerHTML=P.events.map(e=>`<article class="timeline-row"><span class="timeline-state ${P.phase(e)==='进行中'?'active':''}">${P.phase(e)}</span><div><b>${esc(e.title)}</b><p>${fmt(e.start)}${e.end?' → '+fmt(e.end):' 起'}</p><small>${esc(e.note)}</small></div></article>`).join('');}
 document.querySelector('#exportExamCalendar').onclick=()=>download('2027国考关键时间.ics',P.ics(),'text/calendar;charset=utf-8');
 const previousTab=setTab;
 setTab=function(value){previousTab(value==='policy'?'discover':value);view.hidden=value!=='policy';if(value==='policy'){tab=value;document.querySelector('#discoveryView').hidden=true;document.querySelector('#assistantView').hidden=true;document.querySelector('#monitorView').hidden=true;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===value));timeline();}};
 document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
 document.addEventListener('visibilitychange',()=>{if(!view.hidden)timeline();});
 function examCard(j){
  const x=P.exam(j),weights=x.weights?.map((w,i)=>['行测','申论','专业 / 外语'][i]+' '+(w*100)+'%').join(' · ')||'需确认专业笔试方案后计算';
  return `<section id="jobExamCard" class="detail-section exam-card"><div class="eyebrow">EXAM PLAN · 2027</div><h3>这个岗位，实际考什么？</h3><dl class="detail-grid"><div><dt>公共科目试卷</dt><dd>${esc(x.type)}</dd></div><div><dt>考试方案</dt><dd>${esc(x.track)}</dd></div><div><dt>笔试成绩权重</dt><dd>${weights}</dd></div><div><dt>面试阶段专业能力测试</dt><dd>${esc(x.interviewTest)}</dd></div></dl><p>行测：11月29日9:00–11:00；申论：14:00–17:00。${x.special?'另考专业 / 外语：11月28日14:00–16:00。考点选直辖市、省会或自治区首府。':''}</p>${x.csrc?`<p><b>证监会采用“公共科目 + 专业科目”考试，专业科目占笔试合成成绩50%。</b>专业类别按岗位确定。</p>${x.topics.length?'<ul>'+x.topics.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p>职位名称未明确专业类别，请确认适用大纲。</p>'}<p class="small muted">所附大纲：专业笔试120分钟、满分100分；证券期货基础知识40道单选，专业知识40道单选和20道多选。题数不等于分值比例。法律、会计、计算机类也需复习证券期货基础知识。会计类不能自带计算器。</p>${link('csrc')}`:''}<p class="small muted">${x.certain?'依据2027公告的笔试规则；面试阶段专业能力测试须另看机关公告。':x.publicOnly?'岗位备注明确只考行测和申论；成绩合成方式请看机关补充公告，未直接套用通用权重。':'本岗位是否参加统一专业 / 外语笔试尚不能从职位属性可靠识别，请核对招录机关公告。'}</p>${x.weights?`<form id="examScoreForm"><h3>笔试成绩试算</h3><p class="small muted">输入百分制成绩，计算加权笔试分；不判断合格线、排名或录取概率。</p><div class="score-inputs">${x.weights.map((w,i)=>`<label>${['行测','申论','专业 / 外语'][i]}<input aria-label="${['行测成绩','申论成绩','专业成绩'][i]}" name="score${i}" type="number" min="0" max="100" step="0.01" required></label>`).join('')}<button class="button subtle" type="submit">计算</button></div><output id="examScoreResult" aria-live="polite"></output></form>`:''}<p class="small">${link('announcement')} · ${link('guide')}</p></section>`;
 }
 const previousDetail=showDetail;
 showDetail=function(id){previousDetail(id);const j=byId.get(id);if(!j)return;document.querySelector('#detailBody > .detail-grid').insertAdjacentHTML('afterend',examCard(j));const f=document.querySelector('#examScoreForm');if(f)f.onsubmit=e=>{e.preventDefault();try{document.querySelector('#examScoreResult').textContent='加权笔试成绩：'+P.score(P.exam(j).weights,[...new FormData(f).values()]).toFixed(2)+' / 100';}catch(err){document.querySelector('#examScoreResult').textContent=err.message;}};};
 timeline();
})();
